mapper.select:
SELECT * FROM ( SELECT a.doctor_user_id doctorUserId, a.company_id companyId, b.user_name userName, c.company_name companyName, a.rep_num repNum FROM ( SELECT doctor_user_id, company_id, count(0) rep_num FROM ( SELECT ifnull( t.doctor_user_id, s.doctor_user_id ) doctor_user_id, company_id, pdf_file_path FROM cust_user_ecg_report s LEFT JOIN cust_user_ecg_report_statistics t ON s.rep_id = t.rep_id WHERE pdf_file_path IS NOT NULL
AND rep_type =#{repType}
AND pdf_time >=#{startDate} AND pdf_time<=#{endDate} ) t1 WHERE doctor_user_id IS NOT NULL AND doctor_user_id IN ( SELECT user_id FROM comm_system_user WHERE company_id =#{companyId} ) GROUP BY doctor_user_id, company_id ) a LEFT JOIN comm_system_user b ON a.doctor_user_id = b.user_id LEFT JOIN comm_company c ON a.company_id = c.company_id ORDER BY user_name, company_name ) TEMP where 1=1
order by ${column} ${order}

SELECT * FROM ( SELECT a.rep_id repId, a.rep_no repNo, a.user_name userName, a.report_date reportDate , a.ecg_start_time ecgStartTime, a.ecg_end_time ecgEndTime, timestampdiff( SECOND, a.ecg_start_time, a.ecg_end_time ) ecgSeconds, ( ( to_days(a.ecg_end_time) - to_days(a.ecg_start_time) ) + 1 ) AS days, ifnull( b.doctor_user_id, a.doctor_user_id ) doctorId, a.pdf_time pdfTime, a.company_id companyId, a.rep_type repType, a.pdf_file_path pdfFilePath, d.mach_sn machSn FROM cust_user_ecg_report a LEFT JOIN cust_user_ecg_report_statistics b ON a.rep_id = b.rep_id LEFT JOIN ( SELECT ta.rep_id AS rep_id, group_concat( DISTINCT tb.mach_sn SEPARATOR ',' ) AS mach_sn FROM ( cust_user_ecg_report_detail ta LEFT JOIN cust_user_ecg_rec tb ON ((ta.ecg_id = tb.ecg_id)) ) GROUP BY ta.rep_id ) d ON (a.rep_id = d.rep_id) ) TEMP where pdfFilePath IS NOT NULL AND pdfTime >=#{startDate} AND pdfTime<= #{endDate}
and ${key} like CONCAT('%',#{tm,jdbcType=VARCHAR}, '%')
order by ${column} ${order}
order by repNo desc

SELECT * FROM ( SELECT a.id, a.rep_id repId, a.valid_duration validDuration, a.ecg_duration ecgDuration, a.beat_num beatNum, a.bpm, a.rr_up_sec2 rrUpSec2, a.rr_up_sec3 rrUpSec3, a.rr_up_sec4 rrUpSec4, a.rr_up_sec5 rrUpSec5, r.user_name userName, r.user_gender userGender, r.age, r.report_date reportDate, c.company_name companyName, r.company_id companyId, r.dept_id deptId, r.user_id userId FROM cust_user_ecg_report_feature_pacemaker a LEFT JOIN cust_user_ecg_report r ON a.rep_id = r.rep_id INNER JOIN comm_company c ON c.company_id = r.company_id ) TEMP where deptId in(select distinct dept_id from comm_user_mng_dept where user_id=#{loginUserId} )
and ${paramName} >#{rrNums}
and bpm >=#{tm}
and bpm <=#{tm}
and reportDate >=#{tm}
and reportDate <=#{tm}
and ${key} like CONCAT('%',#{tm,jdbcType=VARCHAR}, '%')
order by ${column} ${order}
order by rrUpSec3 desc
